{"implementation":"def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "nodes" not in case or "required_symbols" not in case:
        raise ValueError("missing required payload fields")

    nodes = case["nodes"]
    required_symbols = case["required_symbols"]
    if not isinstance(nodes, list):
        raise ValueError("nodes must be an array")
    if not isinstance(required_symbols, list) or not all(isinstance(s, str) for s in required_symbols):
        raise ValueError("required_symbols must be an array of strings")

    by_id = {}
    ordered_nodes = []
    for node in nodes:
        if not isinstance(node, dict):
            raise ValueError("each node must be an object")
        for field in ("id", "parent", "symbol", "depth", "removable", "utility"):
            if field not in node:
                raise ValueError("node missing required field")
        node_id = node["id"]
        parent = node["parent"]
        symbol = node["symbol"]
        depth = node["depth"]
        removable = node["removable"]
        if not isinstance(node_id, str):
            raise ValueError("node id must be a string")
        if node_id in by_id:
            raise ValueError("duplicate node id")
        if parent is not None and not isinstance(parent, str):
            raise ValueError("parent must be null or a string")
        if not isinstance(symbol, str):
            raise ValueError("symbol must be a string")
        if not isinstance(depth, int) or isinstance(depth, bool) or depth < 0:
            raise ValueError("depth must be a non-negative integer")
        if not isinstance(removable, bool):
            raise ValueError("removable must be a boolean")
        by_id[node_id] = node
        ordered_nodes.append(node)

    root_count = 0
    for node in ordered_nodes:
        parent = node["parent"]
        if parent is None:
            root_count += 1
        elif parent not in by_id:
            raise ValueError("parent id does not reference a node")
    if root_count != 1:
        raise ValueError("there must be exactly one root")

    required = set(required_symbols)
    retained = set(by_id.keys())
    removed = []

    def required_symbols_represented(candidate_retained):
        represented = set()
        for node_id in candidate_retained:
            represented.add(by_id[node_id]["symbol"])
        return required.issubset(represented)

    if not required_symbols_represented(retained):
        raise ValueError("required symbols are not represented")

    candidates = sorted(ordered_nodes, key=lambda n: (-n["depth"], n["id"]))
    for node in candidates:
        node_id = node["id"]
        if node_id not in retained:
            continue
        if node["parent"] is None:
            continue
        if not node["removable"]:
            continue
        if node["symbol"] in required:
            continue

        has_retained_child = False
        for other in ordered_nodes:
            if other["parent"] == node_id and other["id"] in retained:
                has_retained_child = True
                break
        if has_retained_child:
            continue

        tentative = set(retained)
        tentative.remove(node_id)
        if required_symbols_represented(tentative):
            retained = tentative
            removed.append(node_id)

    return {
        "removed_node_ids": removed,
        "retained_node_ids": sorted(retained),
    }
"}
